#include <httplib.h>
#include <nlohmann/json.hpp>
#include <sqlite3.h>
#include <curl/curl.h>
#include <cstdlib>
#include <iostream>
#include <string>
#include <vector>
#include <random>
#include <sstream>
#include <iomanip>
#include <ctime>
#include <mutex>
#include <algorithm>
#include <cctype>
#include <stdexcept>
using json=nlohmann::json;
static sqlite3* db=nullptr; static std::mutex dbMutex;
std::string env(const char* k,const std::string& fallback=""){const char* v=std::getenv(k);return v?std::string(v):fallback;}
std::string now(){std::time_t t=std::time(nullptr);std::tm tm{};gmtime_r(&t,&tm);char b[32];std::strftime(b,sizeof(b),"%Y-%m-%dT%H:%M:%SZ",&tm);return b;}
void sql(const std::string& q){char* err=nullptr;if(sqlite3_exec(db,q.c_str(),nullptr,nullptr,&err)!=SQLITE_OK){std::string e=err?err:"sqlite error";sqlite3_free(err);throw std::runtime_error(e);}}
std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='\'')o+="''";else o+=c;}return o;}
json queryOne(const std::string&q){sqlite3_stmt* st=nullptr;json out=nullptr;std::lock_guard<std::mutex> lock(dbMutex);if(sqlite3_prepare_v2(db,q.c_str(),-1,&st,nullptr)!=SQLITE_OK)throw std::runtime_error(sqlite3_errmsg(db));if(sqlite3_step(st)==SQLITE_ROW){out=json::object();for(int i=0;i<sqlite3_column_count(st);++i){const char*n=sqlite3_column_name(st,i);const unsigned char*v=sqlite3_column_text(st,i);out[n]=v?reinterpret_cast<const char*>(v):"";}}sqlite3_finalize(st);return out;}
json queryAll(const std::string&q){sqlite3_stmt* st=nullptr;json arr=json::array();std::lock_guard<std::mutex> lock(dbMutex);if(sqlite3_prepare_v2(db,q.c_str(),-1,&st,nullptr)!=SQLITE_OK)throw std::runtime_error(sqlite3_errmsg(db));while(sqlite3_step(st)==SQLITE_ROW){json r=json::object();for(int i=0;i<sqlite3_column_count(st);++i){const char*n=sqlite3_column_name(st,i);const unsigned char*v=sqlite3_column_text(st,i);r[n]=v?reinterpret_cast<const char*>(v):"";}arr.push_back(r);}sqlite3_finalize(st);return arr;}
void execSql(const std::string&q){std::lock_guard<std::mutex> lock(dbMutex);sql(q);}
std::string randomToken(){std::random_device rd;std::mt19937_64 gen(rd());std::uniform_int_distribution<unsigned long long>d;std::ostringstream o;o<<std::hex<<d(gen)<<d(gen);return o.str();}
size_t writeCb(void* contents,size_t size,size_t nmemb,void* user){auto* s=static_cast<std::string*>(user);s->append(static_cast<char*>(contents),size*nmemb);return size*nmemb;}
std::string urlEncode(CURL* c,const std::string&s){char*p=curl_easy_escape(c,s.c_str(),(int)s.size());std::string r=p?p:"";if(p)curl_free(p);return r;}
struct HttpResult{long status=0;std::string body;};
HttpResult twilioPost(const std::string& path,const std::string& form){std::string sid=env("TWILIO_ACCOUNT_SID"),token=env("TWILIO_AUTH_TOKEN");if(sid.empty()||token.empty())throw std::runtime_error("SMS provider is not configured. Set TWILIO_ACCOUNT_SID and TWILIO_AUTH_TOKEN on the backend.");CURL*c=curl_easy_init();if(!c)throw std::runtime_error("Unable to initialize SMS client.");HttpResult out;std::string url=(path.rfind("/v2/Services/",0)==0?"https://verify.twilio.com":"https://api.twilio.com/2010-04-01/Accounts/"+sid)+path;curl_easy_setopt(c,CURLOPT_URL,url.c_str());curl_easy_setopt(c,CURLOPT_POST,1L);curl_easy_setopt(c,CURLOPT_POSTFIELDS,form.c_str());curl_easy_setopt(c,CURLOPT_USERNAME,sid.c_str());curl_easy_setopt(c,CURLOPT_PASSWORD,token.c_str());curl_easy_setopt(c,CURLOPT_WRITEFUNCTION,writeCb);curl_easy_setopt(c,CURLOPT_WRITEDATA,&out.body);curl_easy_setopt(c,CURLOPT_TIMEOUT,15L);curl_easy_setopt(c,CURLOPT_USERAGENT,"AniSiddSafety/1.0");out.status=0;CURLcode rc=curl_easy_perform(c);if(rc==CURLE_OK)curl_easy_getinfo(c,CURLINFO_RESPONSE_CODE,&out.status);std::string err=curl_easy_strerror(rc);curl_easy_cleanup(c);if(rc!=CURLE_OK)throw std::runtime_error("SMS provider connection failed: "+err);return out;}
std::string twilioVerifyPath(){auto sid=env("TWILIO_VERIFY_SERVICE_SID");if(sid.empty())throw std::runtime_error("Set TWILIO_VERIFY_SERVICE_SID to a Verify service configured for 5-digit codes.");return "/v2/Services/"+sid;}
void sendVerify(const std::string& phone){CURL*c=curl_easy_init();if(!c)throw std::runtime_error("Unable to initialize verification client.");std::string form="To="+urlEncode(c,phone)+"&Channel=sms";curl_easy_cleanup(c);auto p=twilioPost(twilioVerifyPath()+"/Verifications",form);if(p.status<200||p.status>=300){std::cerr<<"Twilio verification start error: "<<p.body<<"\n";throw std::runtime_error("Could not send OTP. Check the phone number, provider configuration, and SMS permissions.");}}
bool checkVerify(const std::string& phone,const std::string& code){std::string sid=env("TWILIO_VERIFY_SERVICE_SID");if(sid.empty())throw std::runtime_error("SMS verification provider is not configured.");CURL*c=curl_easy_init();if(!c)throw std::runtime_error("Unable to initialize verification client.");std::string form="To="+urlEncode(c,phone)+"&Code="+urlEncode(c,code);curl_easy_cleanup(c);auto p=twilioPost(twilioVerifyPath()+"/VerificationCheck",form);if(p.status<200||p.status>=300){std::cerr<<"Twilio verification check error: "<<p.body<<"\n";return false;}try{return json::parse(p.body).value("status","")=="approved";}catch(...){return false;}}
void sendSms(const std::string& to,const std::string& body){std::string from=env("TWILIO_FROM_NUMBER");if(from.empty())throw std::runtime_error("Set TWILIO_FROM_NUMBER to an SMS-enabled Twilio number.");CURL*c=curl_easy_init();if(!c)throw std::runtime_error("SMS client unavailable");std::string form="To="+urlEncode(c,to)+"&From="+urlEncode(c,from)+"&Body="+urlEncode(c,body);curl_easy_cleanup(c);auto p=twilioPost("/Messages.json",form);if(p.status<200||p.status>=300){std::cerr<<"Twilio SMS error: "<<p.body<<"\n";throw std::runtime_error("SMS provider rejected a message.");}}
std::string bearer(const httplib::Request& req){auto h=req.get_header_value("Authorization");const std::string pre="Bearer ";return h.rfind(pre,0)==0?h.substr(pre.size()):"";}
json userForToken(const std::string&t){if(t.empty())return nullptr;return queryOne("SELECT u.id,u.phone,u.name,u.email FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token='"+esc(t)+"'");}
void jsonOut(httplib::Response&res,const json&j,int status=200){res.status=status;res.set_content(j.dump(),"application/json; charset=utf-8");}
void fail(httplib::Response&res,const std::string&m,int status=400){jsonOut(res,{{"error",m}},status);}
json bodyJson(const httplib::Request&req){try{return json::parse(req.body);}catch(...){throw std::runtime_error("Request body must be valid JSON.");}}
std::string needString(const json&j,const char*k){if(!j.contains(k)||!j[k].is_string())throw std::runtime_error(std::string("Missing field: ")+k);return j[k].get<std::string>();}
bool validPhone(const std::string&p){if(p.size()!=13||p.rfind("+91",0)!=0)return false;for(size_t i=3;i<p.size();++i)if(!std::isdigit((unsigned char)p[i]))return false;return true;}
void requireAuth(const httplib::Request&req,httplib::Response&res,json&user){user=userForToken(bearer(req));if(user.is_null())fail(res,"Authentication required. Please sign in again.",401);}
int main(){curl_global_init(CURL_GLOBAL_DEFAULT);std::string dbpath=env("ANISIDD_DB","anisidd.sqlite3");if(sqlite3_open(dbpath.c_str(),&db)!=SQLITE_OK){std::cerr<<"Cannot open database\n";return 1;}sql("PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;");sql("CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, phone TEXT UNIQUE NOT NULL, name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);");sql("CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);");sql("CREATE TABLE IF NOT EXISTS contacts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT NOT NULL,phone TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE(user_id,phone));");sql("CREATE TABLE IF NOT EXISTS locations(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,latitude REAL,longitude REAL,accuracy REAL,recorded_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);");sql("CREATE TABLE IF NOT EXISTS sos_events(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,latitude REAL,longitude REAL,maps_url TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);");
 httplib::Server svr;svr.set_payload_max_length(1024*1024);svr.set_default_headers({{"Access-Control-Allow-Origin",env("CORS_ORIGIN","http://localhost:8080")},{"Access-Control-Allow-Headers","Content-Type, Authorization"},{"Access-Control-Allow-Methods","GET, POST, DELETE, OPTIONS"}});svr.Options(R"(/.*)",[](const auto&,auto&res){res.status=204;});
 svr.Get("/api/health",[](const auto&,auto&res){jsonOut(res,{{"ok",true},{"service","AniSidd Safety API"}});});
 svr.Post("/api/auth/start",[](const auto&req,auto&res){try{auto j=bodyJson(req);auto phone=needString(j,"phone"),intent=j.value("intent","login");if(!validPhone(phone))return fail(res,"Use a valid +91 Indian mobile number.");auto u=queryOne("SELECT id FROM users WHERE phone='"+esc(phone)+"'");bool registered=!u.is_null();if(intent=="login"&&!registered)return fail(res,"This number is not registered. Choose Create account to sign up.",404);if(intent=="signup"&&registered)return fail(res,"This number is already registered. Choose Log in.",409);sendVerify(phone);jsonOut(res,{{"ok",true},{"registered",registered},{"message","A 5-digit OTP has been requested by SMS."}});}catch(const std::exception&e){fail(res,e.what(),502);}});
 svr.Post("/api/auth/verify",[](const auto&req,auto&res){try{auto j=bodyJson(req);auto phone=needString(j,"phone"),code=needString(j,"code"),intent=j.value("intent","login");if(!validPhone(phone)||code.size()!=5||!std::all_of(code.begin(),code.end(),[](unsigned char c){return std::isdigit(c);}))return fail(res,"Enter a valid phone number and 5-digit OTP.");if(!checkVerify(phone,code))return fail(res,"OTP is invalid or expired.",401);auto u=queryOne("SELECT id,phone,name,email FROM users WHERE phone='"+esc(phone)+"'");if(u.is_null()){if(intent!="signup")return fail(res,"Number is not registered. Please sign up.",404);execSql("INSERT INTO users(phone,name,email,created_at) VALUES('"+esc(phone)+"','','','"+now()+"');");u=queryOne("SELECT id,phone,name,email FROM users WHERE phone='"+esc(phone)+"'");}else if(intent=="signup")return fail(res,"This number is already registered. Please log in.",409);auto token=randomToken();execSql("INSERT INTO sessions(token,user_id,created_at) VALUES('"+token+"',"+u["id"].get<std::string>()+",'"+now()+"');");jsonOut(res,{{"ok",true},{"token",token},{"user",u}});}catch(const std::exception&e){fail(res,e.what());}});
 svr.Post("/api/auth/logout",[](const auto&req,auto&res){auto t=bearer(req);if(!t.empty())execSql("DELETE FROM sessions WHERE token='"+esc(t)+"'");jsonOut(res,{{"ok",true}});});
 svr.Get("/api/profile",[](const auto&req,auto&res){json u;requireAuth(req,res,u);if(u.is_null())return;jsonOut(res,{{"user",u}});});
 svr.Post("/api/profile",[](const auto&req,auto&res){try{json u;requireAuth(req,res,u);if(u.is_null())return;auto j=bodyJson(req);auto name=needString(j,"name"),email=j.value("email","");if(name.empty()||name.size()>120||email.size()>254)return fail(res,"Name or email is invalid.");execSql("UPDATE users SET name='"+esc(name)+"',email='"+esc(email)+"' WHERE id="+u["id"].get<std::string>()+";");u=queryOne("SELECT id,phone,name,email FROM users WHERE id="+u["id"].get<std::string>());jsonOut(res,{{"user",u}});}catch(const std::exception&e){fail(res,e.what());}});
 svr.Get("/api/contacts",[](const auto&req,auto&res){json u;requireAuth(req,res,u);if(u.is_null())return;jsonOut(res,{{"contacts",queryAll("SELECT id,name,phone FROM contacts WHERE user_id="+u["id"].get<std::string>()+" ORDER BY id DESC")}});});
 svr.Post("/api/contacts",[](const auto&req,auto&res){try{json u;requireAuth(req,res,u);if(u.is_null())return;auto j=bodyJson(req);auto name=needString(j,"name"),phone=needString(j,"phone");if(name.empty()||name.size()>120||!validPhone(phone))return fail(res,"Enter a contact name and valid +91 mobile number.");execSql("INSERT INTO contacts(user_id,name,phone,created_at) VALUES("+u["id"].get<std::string>()+",'"+esc(name)+"','"+esc(phone)+"','"+now()+"');");auto c=queryOne("SELECT id,name,phone FROM contacts WHERE user_id="+u["id"].get<std::string>()+" AND phone='"+esc(phone)+"'");jsonOut(res,{{"contact",c}});}catch(const std::exception&e){fail(res,e.what());}});
 svr.Delete(R"(/api/contacts/([0-9]+))",[](const auto&req,auto&res){json u;requireAuth(req,res,u);if(u.is_null())return;auto id=req.matches[1].str();execSql("DELETE FROM contacts WHERE id="+id+" AND user_id="+u["id"].get<std::string>()+";");jsonOut(res,{{"ok",true}});});
 svr.Post("/api/location",[](const auto&req,auto&res){try{json u;requireAuth(req,res,u);if(u.is_null())return;auto j=bodyJson(req);if(!j.contains("latitude")||!j.contains("longitude")||!j["latitude"].is_number()||!j["longitude"].is_number())return fail(res,"Valid coordinates are required.");double lat=j["latitude"],lon=j["longitude"],acc=j.value("accuracy",0.0);if(lat < -90||lat>90||lon < -180||lon>180)return fail(res,"Coordinates are out of range.");auto at=j.value("recordedAt",now());execSql("INSERT INTO locations(user_id,latitude,longitude,accuracy,recorded_at) VALUES("+u["id"].get<std::string>()+","+std::to_string(lat)+","+std::to_string(lon)+","+std::to_string(acc)+",'"+esc(at)+"');");jsonOut(res,{{"ok",true}});}catch(const std::exception&e){fail(res,e.what());}});
 svr.Post("/api/sos",[](const auto&req,auto&res){try{json u;requireAuth(req,res,u);if(u.is_null())return;auto j=bodyJson(req);bool has=j.contains("latitude")&&j["latitude"].is_number()&&j.contains("longitude")&&j["longitude"].is_number();std::string maps=j.value("googleMapsUrl","");std::string status="recorded; contact delivery pending";std::string lat=has?std::to_string(j["latitude"].get<double>()):"NULL",lon=has?std::to_string(j["longitude"].get<double>()):"NULL";execSql("INSERT INTO sos_events(user_id,latitude,longitude,maps_url,status,created_at) VALUES("+u["id"].get<std::string>()+","+lat+","+lon+",'"+esc(maps)+"','"+status+"','"+now()+"');");auto contacts=queryAll("SELECT name,phone FROM contacts WHERE user_id="+u["id"].get<std::string>());int sent=0,failed=0;std::string message="EMERGENCY SOS from "+u.value("name",std::string("AniSidd user"))+". Location: "+(maps.empty()?"not available":maps)+". If this is an emergency, contact local emergency services.";for(const auto&c:contacts){try{sendSms(c["phone"].get<std::string>(),message);sent++;}catch(const std::exception&e){failed++;std::cerr<<"Contact SMS failed: "<<e.what()<<"\n";}}status="recorded; sms sent="+std::to_string(sent)+"; sms failed="+std::to_string(failed);execSql("UPDATE sos_events SET status='"+esc(status)+"' WHERE id=(SELECT MAX(id) FROM sos_events WHERE user_id="+u["id"].get<std::string>()+");");jsonOut(res,{{"ok",true},{"status",status},{"sent",sent},{"failed",failed},{"message","SOS event recorded. SMS sent to "+std::to_string(sent)+" contact(s). "+(failed?std::to_string(failed)+" message(s) failed. ":"")+"This app does not automatically dispatch police; call 112 directly for immediate danger."}});}catch(const std::exception&e){fail(res,e.what(),500);}});
 svr.Get("/api/history",[](const auto&req,auto&res){json u;requireAuth(req,res,u);if(u.is_null())return;jsonOut(res,{{"events",queryAll("SELECT id,status,created_at,latitude,longitude,maps_url FROM sos_events WHERE user_id="+u["id"].get<std::string>()+" ORDER BY id DESC LIMIT 100")}});});
 svr.Get("/api/admin/overview",[](const auto&req,auto&res){auto expected=env("ADMIN_API_KEY");auto supplied=req.get_header_value("X-Admin-Key");if(expected.empty()||supplied.empty()||supplied!=expected)return fail(res,"Admin access denied.",403);jsonOut(res,{{"users",queryAll("SELECT id,phone,name,email,created_at FROM users ORDER BY id DESC LIMIT 500")},{"contacts",queryAll("SELECT id,user_id,name,phone,created_at FROM contacts ORDER BY id DESC LIMIT 1000")},{"locations",queryAll("SELECT l.id,l.user_id,u.phone,l.latitude,l.longitude,l.accuracy,l.recorded_at FROM locations l JOIN users u ON u.id=l.user_id ORDER BY l.id DESC LIMIT 500")},{"sos_events",queryAll("SELECT e.id,e.user_id,u.phone,e.latitude,e.longitude,e.maps_url,e.status,e.created_at FROM sos_events e JOIN users u ON u.id=e.user_id ORDER BY e.id DESC LIMIT 500")}});});
 int port=std::stoi(env("PORT","8080"));std::cout<<"AniSidd Safety API listening on http://127.0.0.1:"<<port<<"\n";std::cout<<"Database: "<<dbpath<<"\n";svr.listen(env("HOST","127.0.0.1"),port);sqlite3_close(db);curl_global_cleanup();}
